/** Entry point CONSISDIA de LIB-CONTROL (L001). Una operación por función documentada. */
public interface LibControlClient {

    enum FuncionConsisDia {
        CONSULTA(1),                     // CONSULTA S151B01SISDIA
        ACTUALIZA_FECHA_CONSULTA(2),
        ACTUALIZA_FECHA_PROCESO(3),
        ACTUALIZA_ESTATUS_BASE_SEMANAL(4),
        HABILITA_FECHA(5),
        ACTUALIZA_FECHA(6),
        ACTUALIZA_STATUS_LOG(7),
        ACTUALIZA_NIVEL_ARCHIVO_MOVS(8),
        ACTUALIZA_NIVEL_BASE(9),
        ACTUALIZA_NIVEL_BASE_Y_ARCHIVO(10);

        public final int codigo;
        FuncionConsisDia(int c) { codigo = c; }
    }

    SistemaDia consulta(int sistema, int csi);                  // F01, la única que usa P600
    void actualizaFechaConsulta(int sistema, int csi, LocalDate f);   // F02
    void actualizaFechaProceso(int sistema, int csi, LocalDate f);    // F03
    void actualizaEstatusBaseSemanal(int sistema, int csi, int st);   // F04
    // F05 a F10 siguen el mismo patrón; el detalle de campos está en el copy (líneas 72 en adelante).
}

/** WKS-S151B01SISDIA: estado del día de un sistema en un CSI. */
public record SistemaDia(
        int sistema, int csi,
        LocalDate fechaProceso,        // FECPRO    9(08) AAAAMMDD
        LocalDate fechaConsulta,       // FECCON
        LocalDate fechaProcesoS151,    // FECPRO151
        int estatusRegistro,           // STAREG
        ArchivoMcp salida, ArchivoMcp movimientos, ArchivoMcp descriptores, ArchivoMcp errores,
        String baseSemanal,            // NOMBDSEM X(17)
        int estatusBaseSemanal,        // STABDSEM
        int numArchivo, int tercerNivel,
        List<ControlDia> dias) {       // CTL-DIA OCCURS 10

    /** Nombre de archivo (X(34)) más pack (X(17)), como los arma MCP. */
    public record ArchivoMcp(String nombre, String pack) {}

    public record ControlDia(LocalDate fechaArchivoMovs,   // FECARCMOV
                             long nivelArchivoMovs,        // NIVARCMOV 9(08)
                             long nivelBaseMovs,           // NIVBDMOV  9(08)
                             int statusLog) {}             // STAARCLOG 9(02)

    public SistemaDia {
        if (dias.size() != 10) throw new IllegalArgumentException("CTL-DIA OCCURS 10 TIMES");
        dias = List.copyOf(dias);
    }
}

@Configuration
public class FechasOperacionalesJobConfig {

    @Bean
    Job despliegueFechas(JobRepository repo, Step consultaSistemas,
                         Sistema500Decider es500, Step librerias500, Step despliega) {
        return new JobBuilder("S151P600", repo)
            .start(consultaSistemas)                 // 000300-LLAMA-LIBCTL: B04 + CONSISMEN + CONSISDIA + L002
            .next(es500).on("CON_500").to(librerias500)   // 000420 L009 y 000440 L012
                .next(despliega)
            .from(es500).on("*").to(despliega)       // 000500-DSP-FECHAS y 000500-DSP-LIBRERIAS
            .end()
            .build();
    }
}
