@Component
@RequiredArgsConstructor
public class LibreriasResolver {

    private final CtlVersClient ctlvers;          // DAME_TIT IN CTLVER
    private final SoporteComsClient coms;         // CSIID OF SOPORTECOMS
    private final P600Properties props;

    public int csiEfectivo() {
        int csi = coms.csiDelHost();
        return props.aliasCsi().getOrDefault(csi, csi);         // 32 -> 10
    }

    public String tituloLibControl() {
        return ctlvers.dameTitulo("S151L001CTL")
                .orElse(props.libControlDefault());              // título compilado de respaldo
    }
}

